using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using Emby.Server.Implementations.Session;

namespace Emby.Tests
{
    public class SessionWebSocketListenerTests
    {
        [Fact]
        public async Task KeepAliveSockets_ShouldLogInformation_WhenInactiveWebSocketsExist()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<SessionWebSocketListener>>();
            var sessionManagerMock = new Mock<Microsoft.AspNetCore.Http.IServiceProvider>();
            var userManagerMock = new Mock<Microsoft.AspNetCore.Http.IServiceProvider>();
            var loggerFactoryMock = new Mock<ILoggerFactory>();

            var listener = new SessionWebSocketListener(
                loggerMock.Object,
                Mock.Of<Microsoft.AspNetCore.Http.IServiceProvider>(),
                Mock.Of<Microsoft.AspNetCore.Http.IServiceProvider>(),
                loggerFactoryMock.Object);

            // Use reflection or internal access to set private fields if needed
            // But better to simulate the internal state directly
            var webSocketMock1 = new Mock<IWebSocketConnection>();
            var webSocketMock2 = new Mock<IWebSocketConnection>();

            // Set LastKeepAliveDate to simulate inactivity
            var now = DateTime.UtcNow;
            webSocketMock1.SetupGet(w => w.LastKeepAliveDate).Returns(now.AddSeconds(-70)); // inactive
            webSocketMock2.SetupGet(w => w.LastKeepAliveDate).Returns(now.AddSeconds(-80)); // inactive

            // Access private _webSockets and _webSocketsLock
            var webSocketsField = typeof(SessionWebSocketListener).GetField("_webSockets", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var webSocketsLockField = typeof(SessionWebSocketListener).GetField("_webSocketsLock", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

            var webSockets = new HashSet<IWebSocketConnection> { webSocketMock1.Object, webSocketMock2.Object };
            webSocketsField.SetValue(listener, webSockets);
            var lockObj = new object();
            webSocketsLockField.SetValue(listener, lockObj);

            // Act
            // Call KeepAliveSockets directly
            await Task.Run(() => typeof(SessionWebSocketListener)
                .GetMethod("KeepAliveSockets", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)
                .Invoke(listener, new object[] { null, null }));

            // Assert
            // Verify that LogInformation was called with the expected message
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Sending ForceKeepAlive message to")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception?, string>>()),
                Times.AtLeastOnce);
        }
    }
}
```

